import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { LayoutDashboard, Users, ShoppingBag, CreditCard, BarChart3, MessageSquare, Settings, LogOut, Shield, User } from 'lucide-react';

const Sidebar = ({ sidebarOpen, onLogout }) => {
  const location = useLocation();

  const navItems = [
    { to: "", label: "Dashboard", icon: <LayoutDashboard /> },
    { to: "users", label: "Utilisateurs", icon: <Users /> },
    { to: "products", label: "Produits", icon: <ShoppingBag /> },
    { to: "orders", label: "Commandes", icon: <CreditCard /> },
    { to: "analytics", label: "Analytique", icon: <BarChart3 /> },
    { to: "messages", label: "Messages", icon: <MessageSquare /> },
    { to: "settings", label: "Paramètres", icon: <Settings /> },
  ];

  const isLinkActive = (to) => {
    return location.pathname.endsWith(to);
  };

  return (
    <aside className={`fixed inset-y-0 left-0 w-64 bg-white dark:bg-neutral-900 transform ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 transition-transform duration-300 z-50 border-r border-neutral-200 dark:border-neutral-800`}>
      <div className="p-6">
        {/* Logo */}
        <div className="flex items-center mb-6">
          <div className="h-10 w-10 bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center rounded-xl">
            <Shield className="h-6 w-6 text-white" />
          </div>
          <h1 className="ml-3 text-xl font-bold text-neutral-900 dark:text-white">AdminPro</h1>
        </div>

        {/* Nav Links */}
        <nav>
          <ul className="space-y-2">
            {navItems.map((item) => (
              <li key={item.to}>
                <Link
                  to={item.to}
                  className={`flex items-center p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors ${isLinkActive(item.to) ? 'bg-primary-500 text-white' : 'text-neutral-700 dark:text-neutral-300'}`}
                >
                  {item.icon}
                  <span className="ml-2">{item.label}</span>
                </Link>
              </li>
            ))}
          </ul>
        </nav>

        {/* Logout */}
        <button 
          onClick={onLogout} 
          className="mt-6 w-full flex items-center justify-center p-2 rounded-lg text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900 transition-colors"
        >
          <LogOut className="mr-2" /> Déconnexion
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;
